    GH_TOKEN: ${{ secrets.GITHUB_TOKEN }}

- name: Comment on Issue
  uses: actions/github-script@v7
  with:
    script: |
      const typescript = '${{ steps.status.outputs.typescript }}';
      const tests = '${{ steps.status.outputs.tests }}';

      let body = '## 🤖 Feature Implementer - Status Update\n\n';

      if (typescript === 'PASS' && tests === 'PASS') {
        body += '✅ **Implementation Complete**\n\n';
        body += '- ✅ TypeScript compiles\n';
        body += '- ✅ Tests pass\n';
        body += '- ✅ PR created: #TODO (link)\n\n';
        body += '**Next:** architecture-skeptic review will run automatically on the PR.\n';
      } else {
        body += '❌ **Implementation Failed**\n\n';
        body += `- ${typescript === 'PASS' ? '✅' : '❌'} TypeScript compilation\n`;
        body += `- ${tests === 'PASS' ? '✅' : '❌'} Tests\n\n`;
        body += '**Action Required:** Check workflow logs and fix errors.\n';
      }

      body += '\n---\n🤖 Automated by feature-implementer agent';

      await github.rest.issues.createComment({
        issue_number: context.issue.number,
        owner: context.repo.owner,
        repo: context.repo.repo,
        body
      });

- name: Check Continuation Need
  id: continuation
  if: steps.status.outputs.typescript == 'PASS' && steps.status.outputs.tests == 'PASS'
  run: |
    # Get recent commits to see what was accomplished
    RECENT_COMMITS=$(git log --oneline -10 || echo "No commits found")

