        body += '**Possible causes:**\n';
        body += '- Agent hit 100-turn limit without completing\n';
        body += '- Agent encountered errors reading files\n';
        body += '- Task description may need clarification\n\n';
        body += '**Action Required:** Check workflow logs or retry with label removal/re-add.\n';
      } else if (typescript === 'PASS' && tests === 'PASS') {
        body += '✅ **Implementation Complete**\n\n';
        body += '- ✅ TypeScript compiles\n';
        body += '- ✅ Tests pass\n';
        body += '- ✅ Changes committed and pushed\n';
        body += '- ✅ PR created (check above)\n\n';
        body += '**Next:** architecture-skeptic review will run automatically on the PR.\n';
      } else {
        body += '❌ **Implementation Failed**\n\n';
        body += `- ${committed === 'true' ? '✅' : '❌'} Changes committed\n`;
        body += `- ${typescript === 'PASS' ? '✅' : '❌'} TypeScript compilation\n`;
        body += `- ${tests === 'PASS' ? '✅' : '❌'} Tests\n\n`;
        body += '**Action Required:** Check workflow logs and fix errors.\n';
      }

      body += '\n---\n🤖 Automated by feature-implementer agent';

      await github.rest.issues.createComment({
        issue_number: context.issue.number,
        owner: context.repo.owner,
        repo: context.repo.repo,
        body
      });

