- name: Check for Retry Context
  id: retry_context
  uses: actions/github-script@v7
  with:
    script: |
      // Check for auto-retry labels
      const issue = await github.rest.issues.get({
        owner: context.repo.owner,
        repo: context.repo.repo,
        issue_number: context.issue.number
      });

      const retryLabels = issue.data.labels
        .map(l => l.name)
        .filter(name => name.startsWith('auto-retry-'));

      let retryCount = 0;
      if (retryLabels.length > 0) {
        const numbers = retryLabels.map(label => {
          const match = label.match(/auto-retry-(\d+)/);
          return match ? parseInt(match[1]) : 0;
        });
        retryCount = Math.max(...numbers);
      }

      core.setOutput('is_retry', retryCount > 0 ? 'true' : 'false');
      core.setOutput('retry_count', retryCount);

- name: Checkout Feature Branch
  run: |
    BRANCH_NAME="feature/${{ steps.feature.outputs.name }}"

    # Check if branch exists remotely
    if git ls-remote --heads origin "$BRANCH_NAME" | grep -q "$BRANCH_NAME"; then
      echo "Branch exists remotely - checking out and pulling latest"
      git fetch origin "$BRANCH_NAME"
      git checkout "$BRANCH_NAME"
      git pull origin "$BRANCH_NAME"
    else
      echo "Creating new branch"
      git checkout -b "$BRANCH_NAME"
    fi

