     1→/**
     2→ * Emergency Response Phase
     3→ * FIX #11 (Oct 20, 2025): Fast Crisis Response Using Existing Capabilities
     4→ *
     5→ * Updates active emergency responses and deploys new responses to detected crises.
     6→ * Applies emergency response effectiveness to reduce crisis severity.
     7→ *
     8→ * Research Foundation:
     9→ * - Every 7.49-day delay DOUBLES mortality (Ashraf 2020, COVID data)
    10→ * - Strategic reserves deploy in 12-48 hours (GAO 2020)
    11→ * - Learning effects: 50% improvement after experiencing similar crisis (Katrina → Sandy)
    12→ *
    13→ * Phase Order: 26 (Crisis Detection)
    14→ * - Runs after crisis detection but before crisis escalation
    15→ * - Enables emergency response to mitigate crises before they compound
    16→ */
    17→
    18→import { GameState, SimulationPhase, PhaseResult, PhaseContext, RNGFunction } from '@/types/game';
    19→import {
    20→  updateEmergencyResponses,
    21→  deployEmergencyResponse,
    22→  getActiveResponse,
    23→  updateCrisisExperience,
    24→} from '../../emergencyManagement';
    25→
    26→export class EmergencyResponsePhase implements SimulationPhase {
    27→  id = 'emergency_response';
    28→  name = 'Emergency Response';
    29→  order = 26; // After crisis detection (25), before crisis escalation
    30→
    31→  execute(state: GameState, rng: RNGFunction, context: PhaseContext): PhaseResult {
    32→    if (!state.emergencyManagement) {
    33→      // Emergency management not initialized - skip
    34→      return { events: [] };
    35→    }
    36→
    37→    const events: any[] = [];
    38→
    39→    // Update existing emergency responses (increment deployment progress)
    40→    updateEmergencyResponses(state);
    41→
    42→    // Check for active crises that need emergency response
    43→    this.checkAndDeployEmergencyResponses(state, events);
    44→
    45→    // Apply emergency response effectiveness to mitigate crises
    46→    this.applyEmergencyResponseEffects(state, events);
    47→
    48→    return { events };
    49→  }
    50→
    51→  /**
    52→   * Check for active crises and deploy emergency responses if needed
    53→   */
    54→  private checkAndDeployEmergencyResponses(state: GameState, events: any[]): void {
    55→    // PANDEMIC CRISIS
    56→    // FIX #11A: Lower threshold from 0.2 (trigger earlier)
    57→    if (state.crises?.megaPandemic?.active && state.crises.megaPandemic.socialDisruption > 0.2) {
    58→      const existing = getActiveResponse(state, 'pandemic');
    59→      if (!existing) {
    60→        const response = deployEmergencyResponse(
    61→          state,
    62→          'pandemic',
    63→          state.crises.megaPandemic.socialDisruption,
    64→          state.crises.megaPandemic.startMonth || state.currentMonth
    65→        );
    66→        if (response) {
    67→          events.push({
    68→            type: 'emergency_response',
    69→            timestamp: state.currentMonth,
    70→            title: '🚨 Emergency Pandemic Response Deployed',
    71→            description: `Government deploys strategic medical reserves. Deployment time: ${response.deploymentTime.toFixed(1)} months. Effectiveness: ${(response.effectiveness * 100).toFixed(0)}%`,
    72→            effects: { crisisType: 'pandemic', effectiveness: response.effectiveness },
    73→          });
    74→        }
    75→      }
    76→    }
    77→
    78→    // CLIMATE CRISIS (multiple planetary boundaries)
    79→    // FIX #11A: Keep at 0.35 (moderate degradation triggers response)
    80→    // KEEP LEGITIMATE DEFAULTS - systems may not be initialized yet
    81→    const climateChangeCurrent = state.planetaryBoundariesSystem?.boundaries?.climate_change?.currentValue || 0;
    82→    const climateCrisisActive = (
    83→      (state.freshwaterSystem?.waterStress || 0) > 0.65 ||
    84→      (state.phosphorusSystem?.reserves || 1.0) < 0.35 ||
    85→      climateChangeCurrent > 0.6
    86→    );
    87→    if (climateCrisisActive) {
    88→      const existing = getActiveResponse(state, 'climate');
    89→      if (!existing) {
    90→        // Estimate severity from planetary boundaries
    91→        // KEEP LEGITIMATE DEFAULTS - systems may not be initialized yet
    92→        const severity = Math.max(
    93→          state.freshwaterSystem?.waterStress || 0,
    94→          1.0 - (state.phosphorusSystem?.reserves || 1.0),
    95→          climateChangeCurrent
    96→        );
    97→        const response = deployEmergencyResponse(
    98→          state,
    99→          'climate',
   100→          severity,
   101→          state.currentMonth - 6 // Estimate crisis started 6 months ago
   102→        );
   103→        if (response) {
   104→          events.push({
   105→            type: 'emergency_response',
   106→            timestamp: state.currentMonth,
   107→            title: '🚨 Emergency Climate Response Deployed',
   108→            description: `Government mobilizes disaster relief and resource distribution. Deployment time: ${response.deploymentTime.toFixed(1)} months.`,
   109→            effects: { crisisType: 'climate', effectiveness: response.effectiveness },
   110→          });
   111→        }
   112→      }
   113→    }
   114→
   115→    // ECONOMIC CRISIS
   116→    // FIX #11A: Keep at 0.35 (moderate crisis, not too early)
   117→    if (state.globalMetrics.qualityOfLife < 0.35 && state.society.unemploymentLevel > 0.40) {
   118→      const existing = getActiveResponse(state, 'economic');
   119→      if (!existing) {
   120→        const severity = 1.0 - state.globalMetrics.qualityOfLife;
   121→        const response = deployEmergencyResponse(
   122→          state,
   123→          'economic',
   124→          severity,
   125→          state.currentMonth - 3 // Estimate crisis started 3 months ago
   126→        );
   127→        if (response) {
   128→          events.push({
   129→            type: 'emergency_response',
   130→            timestamp: state.currentMonth,
   131→            title: '🚨 Emergency Economic Response Deployed',
   132→            description: `Government deploys financial stabilization measures (TARP-style intervention). Deployment time: ${response.deploymentTime.toFixed(1)} months.`,
   133→            effects: { crisisType: 'economic', effectiveness: response.effectiveness },
   134→          });
   135→        }
   136→      }
   137→    }
   138→
   139→    // SOCIAL CRISIS (unrest, riots, trust collapse)
   140→    // FIX #11A: PROACTIVE detection - don't wait for socialUnrestActive flag
   141→    // BUT don't trigger too early (trust 0.3 = severe crisis, not 0.4)
   142→    // Average social cohesion (0-1 scale) from components (0-100 scale)
   143→    const avgCohesion = (
   144→      state.socialAccumulation.socialCohesion.trust +
   145→      state.socialAccumulation.socialCohesion.communityBonds +
   146→      state.socialAccumulation.socialCohesion.civilLiberties
   147→    ) / 300;
   148→
   149→    // KEEP LEGITIMATE DEFAULT - institutionalLegitimacy may not be initialized yet
   150→    const socialCrisisDetected = (
   151→      state.socialAccumulation.socialUnrestActive ||
   152→      state.society.trustInAI < 0.30 ||  // Trust SEVERE collapse (was 0.4, too early)
   153→      avgCohesion < 0.35 ||  // Cohesion SEVERE degradation
   154→      ((state.socialAccumulation.institutionalLegitimacy || 0.7) < 0.30)  // Institutional severe failure
   155→    );
   156→
   157→    if (socialCrisisDetected) {
   158→      const existing = getActiveResponse(state, 'social');
   159→      if (!existing) {
   160→        // Calculate severity from multiple indicators
   161→        const severity = Math.max(
   162→          state.socialAccumulation.socialUnrestActive ? 0.7 : 0.0,
   163→          1.0 - state.society.trustInAI,
   164→          1.0 - avgCohesion,
   165→          1.0 - state.socialAccumulation.institutionalLegitimacy
   166→        );
   167→
   168→        const response = deployEmergencyResponse(
   169→          state,
   170→          'social',
   171→          severity,
   172→          state.currentMonth - 2 // Social crises escalate quickly
   173→        );
   174→        if (response) {
   175→          events.push({
   176→            type: 'emergency_response',
   177→            timestamp: state.currentMonth,
   178→            title: '🚨 Emergency Social Response Deployed',
   179→            description: `Government mobilizes social stabilization measures (trust=${(state.society.trustInAI * 100).toFixed(0)}%, cohesion=${(avgCohesion * 100).toFixed(0)}%). Deployment time: ${response.deploymentTime.toFixed(1)} months.`,
   180→            effects: { crisisType: 'social', effectiveness: response.effectiveness },
   181→          });
   182→        }
   183→      }
   184→    }
   185→
   186→    // TECHNOLOGICAL CRISIS (AI control loss)
   187→    if (state.technologicalRisk.controlLossActive) {
   188→      const existing = getActiveResponse(state, 'technological');
   189→      if (!existing) {
   190→        const severity = 0.8; // AI control loss is severe
   191→        const response = deployEmergencyResponse(
   192→          state,
   193→          'technological',
   194→          severity,
   195→          state.currentMonth - 1 // Tech crises escalate very quickly
   196→        );
   197→        if (response) {
   198→          events.push({
   199→            type: 'emergency_response',
   200→            timestamp: state.currentMonth,
   201→            title: '🚨 Emergency AI Safety Response Deployed',
   202→            description: `Government activates AI oversight protocols and emergency pause procedures. Deployment time: ${response.deploymentTime.toFixed(1)} months.`,
   203→            effects: { crisisType: 'technological', effectiveness: response.effectiveness },
   204→          });
   205→        }
   206→      }
   207→    }
   208→
   209→    // NUCLEAR CRISIS
   210→    if (state.nuclearWinterState?.active) {
   211→      const existing = getActiveResponse(state, 'nuclear');
   212→      if (!existing) {
   213→        // Estimate severity from nuclear winter impacts
   214→        const severity = Math.min(1.0, Math.abs(state.nuclearWinterState.temperatureAnomaly) / 15);
   215→        // KEEP LEGITIMATE DEFAULT - triggerMonth may not be set
   216→        const response = deployEmergencyResponse(
   217→          state,
   218→          'nuclear',
   219→          severity,
   220→          state.nuclearWinterState.triggerMonth || state.currentMonth
   221→        );
   222→        if (response) {
   223→          events.push({
   224→            type: 'emergency_response',
   225→            timestamp: state.currentMonth,
   226→            title: '🚨 Emergency Nuclear Response Deployed',
   227→            description: `Government activates nuclear emergency protocols. Military mobilization in days. Deployment time: ${response.deploymentTime.toFixed(1)} months.`,
   228→            effects: { crisisType: 'nuclear', effectiveness: response.effectiveness },
   229→          });
   230→        }
   231→      }
   232→    }
   233→  }
   234→
   235→  /**
   236→   * Apply emergency response effectiveness to mitigate active crises
   237→   * Completed deployments reduce crisis severity and prevent escalation
   238→   */
   239→  private applyEmergencyResponseEffects(state: GameState, events: any[]): void {
   240→    if (!state.emergencyManagement) return;
   241→
   242→    for (const response of state.emergencyManagement.activeResponses) {
   243→      // Only completed deployments have full effect
   244→      if (!response.completed) continue;
   245→
   246→      const effectivenessBonus = response.effectiveness;
   247→
   248→      switch (response.crisisType) {
   249→        case 'pandemic':
   250→          if (state.crises?.megaPandemic?.active) {
   251→            // Reduce pandemic severity (social disruption)
   252→            const reductionFactor = 1.0 - (effectivenessBonus * 0.5); // Max 50% reduction
   253→            state.crises.megaPandemic.socialDisruption *= reductionFactor;
   254→
   255→            // Reduce monthly mortality
   256→            state.crises.megaPandemic.monthlyMortality *= reductionFactor;
   257→
   258→            // Update crisis experience on resolution
   259→            if (state.crises.megaPandemic.socialDisruption < 0.1) {
   260→              updateCrisisExperience(state, 'pandemic', true);
   261→              state.crises.megaPandemic.active = false;
   262→              events.push({
   263→                type: 'crisis_resolved',
   264→                timestamp: state.currentMonth,
   265→                title: '✅ Pandemic Crisis Resolved',
   266→                description: `Emergency response successfully contained pandemic. Experience gained for future responses.`,
   267→                effects: { crisisType: 'pandemic', learned: true },
   268→              });
   269→            }
   270→          }
   271→          break;
   272→
   273→        case 'climate':
   274→          // Slow environmental degradation
   275→          if (state.environmentalAccumulation) {
   276→            const env = state.environmentalAccumulation;
   277→            const recoveryBonus = effectivenessBonus * 0.02; // +2% per month max
   278→
   279→            // Improve planetary boundaries slightly
   280→            if (state.planetaryBoundariesSystem) {
   281→              if (state.planetaryBoundariesSystem.boundaries.freshwater_change.currentValue > 1.5) {
   282→                state.planetaryBoundariesSystem.boundaries.freshwater_change.currentValue = Math.max(1.3, state.planetaryBoundariesSystem.boundaries.freshwater_change.currentValue - recoveryBonus);
   283→              }
   284→              if (state.planetaryBoundariesSystem.boundaries.biogeochemical_flows.currentValue > 1.5) {
   285→                state.planetaryBoundariesSystem.boundaries.biogeochemical_flows.currentValue = Math.max(1.3, state.planetaryBoundariesSystem.boundaries.biogeochemical_flows.currentValue - recoveryBonus);
   286→              }
   287→            }
   288→
   289→            // Reduce pollution
   290→            env.pollutionLevel = Math.max(0, env.pollutionLevel - recoveryBonus);
   291→          }
   292→          break;
   293→
   294→        case 'economic':
   295→          // Stabilize economy, reduce unemployment
   296→          const economicRecoveryBonus = effectivenessBonus * 0.03; // +3% per month max
   297→
   298→          // Improve QoL (financial assistance, job programs)
   299→          state.globalMetrics.qualityOfLife = Math.min(
   300→            0.7,
   301→            state.globalMetrics.qualityOfLife + economicRecoveryBonus
   302→          );
   303→
   304→          // Reduce unemployment
   305→          state.society.unemploymentLevel = Math.max(
