     1→/**
     2→ * Government Core Orchestrator
     3→ *
     4→ * Main decision-making and action execution logic for the government agent.
     5→ * This module coordinates action selection and execution while delegating
     6→ * to specialized action modules.
     7→ */
     8→
     9→import { GameState, GameEvent } from '@/types/game';
    10→import { ActionResult, GameAction } from '@/simulation/agents/types';
    11→import { getTrustInAIForPolicy, getTrustInAI } from '@/simulation/socialCohesion';
    12→import {
    13→  calculateObservableAICapability,
    14→  calculateTotalCapabilityFromProfile
    15→} from '@/simulation/calculations';
    16→import {
    17→  CAPABILITY_CONCERNING,
    18→  CAPABILITY_DANGEROUS,
    19→  CAPABILITY_SYSTEMIC_RISK,
    20→  classifyAIThreatLevel
    21→} from '../capabilityThresholds';  // FIX #8 (Oct 18, 2025)
    22→
    23→// Import from new modular structure
    24→import { migratedActions } from '../actions';
    25→
    26→/**
    27→ * Get all available government actions
    28→ */
    29→export function getAllGovernmentActions(): GameAction[] {
    30→  return migratedActions;
    31→}
    32→
    33→/**
    34→ * Select which action the government should take
    35→ * Uses priority-based selection weighted by unemployment and economic stage
    36→ */
    37→export function selectGovernmentAction(
    38→  state: GameState,
    39→  random: () => number = Math.random
    40→): GameAction | null {
    41→  const availableActions = getAllGovernmentActions().filter(action =>
    42→    action.canExecute(state)
    43→  );
    44→
    45→  if (availableActions.length === 0) return null;
    46→
    47→  // Oct 24, 2025: Log climate priority configuration (first month only)
    48→  if (state.currentMonth === 0 && state.config.climatePriority) {
    49→    console.log(`\n[Government] Climate Priority: ${state.config.climatePriority.preset}`);
    50→    console.log(`  Climate weight: ${(state.config.climatePriority.weights.climate * 100).toFixed(0)}%`);
    51→    console.log(`  Economic weight: ${(state.config.climatePriority.weights.economic * 100).toFixed(0)}%`);
    52→    console.log(`  Policy effectiveness: ${(state.config.climatePriority.policyEffectiveness * 100).toFixed(1)}%/year`);
    53→  }
    54→
    55→  const unemploymentLevel = state.society.unemploymentLevel;
    56→  const economicStage = Math.floor(state.globalMetrics.economicTransitionStage);
    57→  // P2.3 UPDATE (Oct 16, 2025): Use power-weighted trust for policy decisions
    58→  // Elite preferences dominate policy-making (Gilens & Page 2014)
    59→  const trustLevel = getTrustInAIForPolicy(state.society);
    60→  const threatLevel = state.aiAgents.filter(ai => ai.escaped).length / state.aiAgents.length;
    61→  // Use OBSERVABLE capability - government makes decisions based on what it can see, not hidden power
    62→  const observableCapability = calculateObservableAICapability(state.aiAgents);
